import json
from collections import deque
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in g]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(cells)
    return out
